'use strict';
/* =====================================================================
   Ledger Admin 2 — enterprise features. Each module only runs when its
   markup is on the page. Depends on core.js (toast, openLayer, ic …).
   ===================================================================== */
(function(){
const k='f';
const store={get(key,d){try{const v=localStorage.getItem('admin2:'+key);return v==null?d:v}catch(e){return d}},set(key,v){try{localStorage.setItem('admin2:'+key,v)}catch(e){}},json(key,d){try{return JSON.parse(localStorage.getItem('admin2:'+key))??d}catch(e){return d}}};
const PAGES=[['Dashboard','index.html','home'],['Approvals','approvals.html','ok'],['Notifications','notifications.html','bell'],['Users','users.html','users'],['Access control','access.html','lock'],['Tenants','tenants.html','globe'],['Reports','reports.html','chart'],['Data import','import.html','upload'],['Audit log','audit.html','list'],['Workflows','workflows.html','bolt'],['Feature flags','flags.html','flag'],['Integrations','integrations.html','link'],['Security center','security.html','lock'],['Compliance','compliance.html','file'],['Billing & usage','billing.html','tag'],['System status','status.html','monitor'],['Organization settings','settings.html','sliders']];
const ACTIONS=[['Invite user','users.html#invite','plus'],['Create report','reports.html','chart'],['Import users from CSV','import.html','upload'],['New automation rule','workflows.html#new','bolt'],['Create API key','integrations.html#key','code'],['Review pending approvals','approvals.html','ok'],['Toggle compact mode','#density','rows'],['Switch theme','#theme','sun'],['Show keyboard shortcuts','#shortcuts','command']];

/* ---------- organisation (tenant) switcher ---------- */
const ORGS=[['Ledger Inc.','Production · EU','#1760B8','LI'],['Ledger Labs','Sandbox · US','#7A3E9D','LL'],['Northwind Retail','Production · US','#2F7D6A','NR'],['Contoso Freight','Staging · EU','#C25B1F','CF']];
const applyOrg=()=>{const o=ORGS[+store.get('org',0)]||ORGS[0];$$('[data-org-name]').forEach(e=>e.textContent=o[0]);$$('[data-org-env]').forEach(e=>e.textContent=o[1]);$$('[data-org-mark]').forEach(e=>{e.textContent=o[3];e.parentElement.style.setProperty('--org-c',o[2])});const bar=document.querySelector('[data-envbar]');if(bar)bar.hidden=!/Sandbox|Staging/.test(o[1]);$$('[data-envbar-text]').forEach(e=>e.textContent=`You are in ${o[0]} (${o[1]}). Changes here don’t affect production.`)};
applyOrg();
document.addEventListener('click',e=>{const o=e.target.closest('[data-org]');if(o){store.set('org',o.dataset.org);applyOrg();toast(k,{title:`Switched to ${ORGS[+o.dataset.org][0]}`,text:ORGS[+o.dataset.org][1]})}});

/* ---------- density ---------- */
const applyDens=()=>{const c=store.get('dens','comfortable')==='compact';document.body.classList.toggle('dn-compact',c);$$('[data-dens]').forEach(b=>b.setAttribute('aria-pressed',String(c)))};applyDens();
const toggleDens=()=>{store.set('dens',store.get('dens','comfortable')==='compact'?'comfortable':'compact');applyDens();toast(k,{title:document.body.classList.contains('dn-compact')?'Compact mode on':'Comfortable mode on'})};
document.addEventListener('click',e=>{if(e.target.closest('[data-dens]'))toggleDens()});

/* ---------- locale formatting ---------- */
const LOC=store.get('locale','en-US'),CUR=store.get('currency','USD');
const fmtAll=(root=document)=>{$$('[data-money]',root).forEach(el=>el.textContent=new Intl.NumberFormat(LOC,{style:'currency',currency:CUR}).format(+el.dataset.money));$$('[data-num]',root).forEach(el=>el.textContent=new Intl.NumberFormat(LOC).format(+el.dataset.num));$$('[data-date]',root).forEach(el=>el.textContent=new Intl.DateTimeFormat(LOC,{dateStyle:'medium'}).format(new Date(el.dataset.date)))};
fmtAll();

/* ---------- command palette + shortcuts ---------- */
function openPalette(){
  const L=openLayer(k,`<div class="ds-dialog cp" role="dialog" aria-label="Command palette"><div class="cp__in">${ic('search')}<input type="text" role="combobox" aria-expanded="true" aria-controls="cp-list" aria-autocomplete="list" placeholder="Search pages, actions and people" autocomplete="off" autofocus><span class="kbd">Esc</span></div><div class="cp__list" id="cp-list" role="listbox" aria-label="Results"></div><div class="cp__foot"><span>↑↓ move</span><span>Enter open</span><span>G then D / U / A / R / S jumps to a page</span></div></div>`,'cp');
  const inp=L.querySelector('input'),list=L.querySelector('[role=listbox]');
  const people=(window.ADMIN_USERS||[]).slice(0,40).map(u=>[u.name,'users.html#'+u.id,'user',u.email]);
  const draw=()=>{const q=inp.value.trim().toLowerCase();const grp=(t,arr)=>{const hits=arr.filter(x=>!q||(x[0]+' '+(x[3]||'')).toLowerCase().includes(q)).slice(0,q?8:6);return hits.length?`<div class="cp__g" role="presentation">${t}</div>`+hits.map(x=>`<div class="ds-opt" role="option" id="cp-${slugify(x[0])}" data-href="${x[1]}">${ic(x[2])}<span class="ds-opt__main"><span class="ds-opt__label">${esc(x[0])}</span>${x[3]?`<span class="ds-opt__desc">${esc(x[3])}</span>`:''}</span></div>`).join(''):''};
    const html=grp('Pages',PAGES)+grp('Actions',ACTIONS)+(q?grp('People',people):'');list.innerHTML=html||`<div class="ds-empty">No results for “${esc(inp.value)}”. Try “users”, “import” or a person’s name.</div>`;moveCur(list,'first',inp)};
  const run=o=>{const h=o.dataset.href;L._close();if(h==='#density')toggleDens();else if(h==='#theme')document.querySelector(`[data-set-theme="${document.documentElement.dataset.theme==='dark'?'light':'dark'}"]`)?.click();else if(h==='#shortcuts')openShortcuts();else location.href=h};
  inp.addEventListener('input',draw);inp.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();moveCur(list,1,inp)}if(e.key==='ArrowUp'){e.preventDefault();moveCur(list,-1,inp)}if(e.key==='Enter'){e.preventDefault();const c=list.querySelector('.is-cur');if(c)run(c)}});
  list.addEventListener('click',e=>{const o=e.target.closest('.ds-opt');if(o)run(o)});draw();
}
const slugify=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-');
function openShortcuts(){openLayer(k,`<div class="ds-dialog" role="dialog" aria-labelledby="sc-t" style="--dlg-w:520px"><div class="ds-dialog__head"><h2 class="ds-dialog__title" id="sc-t">Keyboard shortcuts</h2><button type="button" class="ds-btn ds-btn--subtle ds-ibtn ds-s" aria-label="Close" data-close>${ic('x')}</button></div><div class="ds-dialog__body"><div class="ds-tablewrap"><table class="ds-table"><caption class="ds-sr">Shortcuts</caption><tbody>${[['Ctrl K','Open command palette'],['/','Focus search'],['?','Show this list'],['G then D','Go to Dashboard'],['G then U','Go to Users'],['G then A','Go to Approvals'],['G then R','Go to Reports'],['G then S','Go to Settings'],['Esc','Close dialogs and menus']].map(([a,b])=>`<tr><td style="width:120px"><span class="kbd">${a}</span></td><td>${b}</td></tr>`).join('')}</tbody></table></div></div><div class="ds-dialog__foot"><button type="button" class="ds-btn ds-btn--primary" data-close><span>Done</span></button></div></div>`)}
let gPressed=0;
document.addEventListener('keydown',e=>{
  const typing=e.target.closest&&e.target.closest('input,textarea,select,[contenteditable="true"]');
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();if(!document.querySelector('.ds-layer--cp'))openPalette();return}
  if(typing)return;
  if(e.key==='?'){e.preventDefault();openShortcuts();return}
  if(e.key.toLowerCase()==='g'){gPressed=Date.now();return}
  if(Date.now()-gPressed<1200){const m={d:'index.html',u:'users.html',a:'approvals.html',r:'reports.html',s:'settings.html'}[e.key.toLowerCase()];if(m){location.href=m}gPressed=0}
},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-palette]'))openPalette();if(e.target.closest('[data-shortcuts]'))openShortcuts()});

/* ---------- session timeout warning ---------- */
function timeoutWarning(){let s=60;const L=openLayer(k,`<div class="ds-dialog" role="alertdialog" aria-labelledby="to-t" aria-describedby="to-d" style="--dlg-w:420px"><div class="ds-dialog__head"><h2 class="ds-dialog__title" id="to-t">Your session is about to end</h2></div><div class="ds-dialog__body"><p id="to-d">For security, you’ll be signed out after 15 minutes of inactivity.</p><div class="timeout-ring" aria-live="polite"><span data-s>1:00</span></div></div><div class="ds-dialog__foot"><button type="button" class="ds-btn" data-close data-signout><span>Sign out</span></button><button type="button" class="ds-btn ds-btn--primary" data-close autofocus><span>Stay signed in</span></button></div></div>`);const t=setInterval(()=>{s--;const el=L.querySelector('[data-s]');if(!el||s<0){clearInterval(t);if(s<0){L._close();toast(k,{title:'Signed out (demo)',v:'warning',text:'In production you would return to the sign-in page.'})}return}el.textContent=`0:${String(s).padStart(2,'0')}`},1000);L.addEventListener('click',e=>{if(e.target.closest('[data-close]')){clearInterval(t);if(!e.target.closest('[data-signout]'))toast(k,{title:'Session extended',v:'success'})}})}
document.addEventListener('click',e=>{if(e.target.closest('[data-timeout-demo]'))timeoutWarning()});

/* ---------- live notifications (bell) ---------- */
const bellCount=()=>document.querySelector('.ad-bell .ds-badge');
const live=document.querySelector('[data-live]');
if(live){const feed=document.querySelector('[data-feed]');const MSG=[['AK',5,'<b>Aiko Kato</b> approved access request <b>AR-118</b>','Access'],['SY',4,'Webhook <b>orders.created</b> recovered after 2 failures','Integrations'],['PN',2,'<b>Priya Nair</b> exported the Q3 revenue report','Reports'],['SY',3,'New sign-in from Porto for <b>maya.ruiz</b>','Security'],['CL',5,'<b>Chen Li</b> enabled flag <b>new-checkout</b> in Staging','Flags']];let i=0,t=null;
  live.addEventListener('change',()=>{if(live.checked){t=setInterval(()=>{const m=MSG[i++%MSG.length];feed.insertAdjacentHTML('afterbegin',`<div class="dx-notif is-unread" role="listitem" tabindex="0" data-read-one><span class="ds-av ds-s" data-c="${m[1]}" role="img" aria-label="${m[0]}">${m[0]}</span><div><div class="dx-notif__t">${m[2]}</div><div class="dx-notif__m">Just now · ${m[3]}</div></div><span data-dot style="width:8px;height:8px;border-radius:50%;background:var(--pri);margin-top:6px" aria-hidden="true"></span></div>`);const b=bellCount();if(b)b.textContent=+b.textContent+1;toast(k,{title:'New notification',text:m[2].replace(/<[^>]+>/g,'')})},6000)}else clearInterval(t)})}

/* ---------- dashboard customisation ---------- */
const wg=document.querySelector('[data-widgets]');
if(wg){const order=store.json('dash-order',null),hidden=new Set(store.json('dash-hidden',[]));
  if(order)order.forEach(id=>{const w=wg.querySelector(`[data-w="${id}"]`);if(w)wg.appendChild(w)});
  const save=()=>{store.set('dash-order',JSON.stringify($$('[data-w]',wg).map(w=>w.dataset.w)));store.set('dash-hidden',JSON.stringify([...hidden]))};
  const paint=()=>{$$('[data-w]',wg).forEach(w=>w.hidden=hidden.has(w.dataset.w));const hl=document.querySelector('[data-hidden-list]');if(hl)hl.innerHTML=hidden.size?`<span class="faint small">Hidden:</span>`+[...hidden].map(id=>`<span class="chip-x">${esc(wg.querySelector(`[data-w="${id}"]`)?.dataset.title||id)}<button type="button" aria-label="Show ${id}" data-show-w="${id}">${ic('plus')}</button></span>`).join(''):''};paint();
  document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-dash]');if(b){const on=!document.body.classList.contains('edit-dash');document.body.classList.toggle('edit-dash',on);b.setAttribute('aria-pressed',String(on));b.querySelector('span').textContent=on?'Done':'Customize';$$('[data-w]',wg).forEach(w=>w.draggable=on);document.querySelector('[data-hidden-list]').hidden=!on;return}
    const h=e.target.closest('[data-hide-w]');if(h){hidden.add(h.closest('[data-w]').dataset.w);save();paint();return}
    const s=e.target.closest('[data-show-w]');if(s){hidden.delete(s.dataset.showW);save();paint();return}
    const m=e.target.closest('[data-move-w]');if(m){const w=m.closest('[data-w]');const sib=+m.dataset.moveW<0?w.previousElementSibling:w.nextElementSibling;if(sib){+m.dataset.moveW<0?wg.insertBefore(w,sib):wg.insertBefore(sib,w);save();m.focus()}return}
    if(e.target.closest('[data-reset-dash]')){store.set('dash-order','null');store.set('dash-hidden','[]');location.reload()}});
  let drag=null;wg.addEventListener('dragstart',e=>{drag=e.target.closest('[data-w]');drag&&drag.classList.add('is-drag')});wg.addEventListener('dragend',()=>{drag&&drag.classList.remove('is-drag');drag=null;save()});wg.addEventListener('dragover',e=>{if(!drag)return;e.preventDefault();const over=e.target.closest('[data-w]');if(over&&over!==drag){const r=over.getBoundingClientRect();wg.insertBefore(drag,(e.clientY-r.top)/r.height>.5?over.nextSibling:over)}})}

/* ---------- users data grid ---------- */
const FIRST=['Maya','Jonas','Aiko','Liam','Priya','Tomás','Ana','Ben','Chen','Dana','Elif','Farid','Grace','Hugo','Ines','Jamal','Kira','Lars','Mei','Nadia','Omar','Paula','Quentin','Rosa','Sven','Tara'];const LAST=['Ruiz','Ortiz','Kato','Shah','Nair','Weber','Costa','Okafor','Li','Park','Demir','Haddad','Kim','Lefèvre','Silva','Brown','Novak','Berg','Wang','Haddad','Farouk','Gomez','Martin','Rossi','Lund','Patel'];
const ROLES=['Administrator','Billing admin','Editor','Viewer','Auditor'],TEAMS=['Engineering','Finance','Sales','Operations','Design','Support','Legal'],STAT=['Active','Active','Active','Active','Invited','Suspended'],LOCS=['Lisbon','Porto','Berlin','New York','Austin','Singapore','London'];
const USERS=window.ADMIN_USERS=Array.from({length:64},(_,i)=>{const f=FIRST[i%FIRST.length],l=LAST[(i*7+Math.floor(i/FIRST.length)*5)%LAST.length];return {id:'u'+(1000+i),name:`${f} ${l}`,email:`${f}.${l}`.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'')+'@ledger.example',role:ROLES[(i*3)%5],team:TEAMS[(i*5)%7],status:STAT[(i*11)%6],mfa:(i*13)%4!==0,last:Math.round(((i*37)%720)/(i%3+1)),loc:LOCS[(i*3)%7],ini:f[0]+l[0],c:(i%5)+1}});
const grid=document.querySelector('[data-grid]');
if(grid){
  const COLS=[['name','Name'],['role','Role'],['team','Team'],['status','Status'],['mfa','MFA'],['loc','Location'],['last','Last active']];
  const ST={page:1,size:10,sort:['name',1],q:'',conds:[],views:null,cols:new Set(store.json('grid-cols',COLS.map(c=>c[0]))),sel:new Set(),view:'all'};
  const VIEWS={all:['All users',[]],admins:['Administrators',[['role','is','Administrator']]],nomfa:['Without MFA',[['mfa','is','No']]],invited:['Pending invites',[['status','is','Invited']]],suspended:['Suspended',[['status','is','Suspended']]]};
  const custom=store.json('grid-views',{});Object.assign(VIEWS,custom);
  const lastTxt=m=>m<1?'Just now':m<60?`${m} min ago`:m<1440?`${Math.round(m/60)} h ago`:`${Math.round(m/1440)} d ago`;
  const val=(u,f)=>f==='mfa'?(u.mfa?'Yes':'No'):u[f];
  const match=(u,[f,op,v])=>{const a=String(val(u,f)).toLowerCase(),b=String(v).toLowerCase();return op==='is'?a===b:op==='is not'?a!==b:op==='contains'?a.includes(b):op==='starts with'?a.startsWith(b):true};
  const rows=()=>{let r=USERS.filter(u=>(!ST.q||(u.name+' '+u.email).toLowerCase().includes(ST.q))&&ST.conds.every(c=>match(u,c)));const [f,d]=ST.sort;r.sort((a,b)=>{const x=f==='last'?a.last:String(val(a,f)),y=f==='last'?b.last:String(val(b,f));return (x>y?1:x<y?-1:0)*d});return r};
  const tbl=grid.querySelector('table'),tb=tbl.tBodies[0],thead=tbl.tHead;
  const badgeS={Active:'success',Invited:'info',Suspended:'danger'};
  const draw=()=>{const all=rows();const pages=Math.max(1,Math.ceil(all.length/ST.size));ST.page=Math.min(ST.page,pages);const slice=all.slice((ST.page-1)*ST.size,ST.page*ST.size);
    thead.innerHTML=`<tr><th class="ds-cellw"><label class="ds-check"><input type="checkbox" data-gall aria-label="Select all on this page"><span class="ds-check__box"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5 9.5 17 19 7"/></svg></span></label></th>${COLS.filter(c=>ST.cols.has(c[0])).map(([f,l])=>`<th scope="col"${ST.sort[0]===f?` aria-sort="${ST.sort[1]>0?'ascending':'descending'}"`:''}${f==='last'?' class="num"':''}><button type="button" class="ds-sort" data-gsort="${f}">${l}${ic('arrow-up')}</button></th>`).join('')}<th class="ds-cellw"><span class="ds-sr">Actions</span></th></tr>`;
    tb.innerHTML=slice.length?slice.map(u=>`<tr data-id="${u.id}" aria-selected="${ST.sel.has(u.id)}"><td class="ds-cellw"><label class="ds-check"><input type="checkbox" data-grow${ST.sel.has(u.id)?' checked':''} aria-label="Select ${esc(u.name)}"><span class="ds-check__box"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5 9.5 17 19 7"/></svg></span></label></td>${COLS.filter(c=>ST.cols.has(c[0])).map(([f])=>`<td${f==='last'?' class="num"':''}>${f==='name'?`<span class="who"><span class="ds-av ds-s" data-c="${u.c}" role="img" aria-label="${esc(u.name)}">${u.ini}</span><span><b><a href="#" data-quick="${u.id}">${esc(u.name)}</a></b><span>${u.email}</span></span></span>`:f==='role'?`<select class="n-select" data-grole="${u.id}" aria-label="Role for ${esc(u.name)}">${ROLES.map(r=>`<option${r===u.role?' selected':''}>${r}</option>`).join('')}</select>`:f==='status'?`<span class="ds-badge ds-badge--${badgeS[u.status]}">${u.status}</span>`:f==='mfa'?(u.mfa?`<span class="pill"><span class="dot"></span>Enabled</span>`:`<span class="pill"><span class="dot warn"></span>Off</span>`):f==='last'?lastTxt(u.last):esc(u[f])}</td>`).join('')}<td class="ds-cellw"><button type="button" class="ds-btn ds-btn--subtle ds-ibtn ds-s" data-quick="${u.id}" aria-label="Quick view ${esc(u.name)}">${ic('panel')}</button></td></tr>`).join(''):`<tr><td colspan="9"><div class="dx-empty"><span class="dx-empty__art">${ic('filter')}</span><h4>No users match</h4><p>Remove a filter or change the search.</p><button type="button" class="ds-btn" data-gclear><span>Clear filters</span></button></div></td></tr>`;
    const a=thead.querySelector('[data-gall]');const ids=slice.map(u=>u.id);const n=ids.filter(id=>ST.sel.has(id)).length;a.checked=n&&n===ids.length;a.indeterminate=n>0&&n<ids.length;
    grid.querySelector('[data-gcount]').textContent=`${all.length} user${all.length===1?'':'s'}`;
    grid.querySelector('[data-gpage]').textContent=`${all.length?(ST.page-1)*ST.size+1:0}–${Math.min(ST.page*ST.size,all.length)} of ${all.length}`;
    grid.querySelector('[data-gprev]').disabled=ST.page<=1;grid.querySelector('[data-gnext]').disabled=ST.page>=pages;
    const bar=grid.querySelector('[data-gbulk]');bar.hidden=!ST.sel.size;bar.querySelector('[data-gsel]').textContent=`${ST.sel.size} selected`;
    const chips=grid.querySelector('[data-gchips]');chips.innerHTML=ST.conds.map((c,i)=>`<span class="chip-x">${COLS.find(x=>x[0]===c[0])[1]} ${c[1]} “${esc(c[2])}”<button type="button" aria-label="Remove filter" data-grm="${i}">${ic('x')}</button></span>`).join('')+(ST.conds.length?`<button type="button" class="ds-btn ds-btn--link ds-s" data-gclear><span>Clear all</span></button>`:'');
    $$('[data-gview]',grid).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.gview===ST.view)));
  };
  const viewsHTML=()=>Object.entries(VIEWS).map(([id,[l]])=>`<button type="button" class="ds-btn ds-s" data-gview="${id}" aria-pressed="false"><span>${esc(l)}</span></button>`).join('')+`<button type="button" class="ds-btn ds-btn--link ds-s" data-gsave><span>Save current view</span></button>`;
  grid.querySelector('[data-gviews]').innerHTML=viewsHTML();
  grid.querySelector('[data-gcols]').innerHTML=COLS.filter(c=>c[0]!=='name').map(([f,l])=>`<div class="ds-opt" role="menuitemcheckbox" aria-checked="${ST.cols.has(f)}" tabindex="-1" data-gcol="${f}"><span class="ds-opt__label">${l}</span>${ic('check','ds-opt__tick')}</div>`).join('');
  grid.addEventListener('click',e=>{const t=e.target;let el;
    if((el=t.closest('[data-gsort]'))){const f=el.dataset.gsort;ST.sort=[f,ST.sort[0]===f?-ST.sort[1]:1];draw();thead.querySelector(`[data-gsort="${f}"]`).focus();return}
    if((el=t.closest('[data-gview]'))){ST.view=el.dataset.gview;ST.conds=VIEWS[ST.view][1].map(c=>[...c]);ST.page=1;draw();return}
    if(t.closest('[data-gsave]')){const name=prompt?null:null;const id='v'+Date.now();const label=`My view ${Object.keys(custom).length+1}`;custom[id]=[label,ST.conds.map(c=>[...c])];VIEWS[id]=custom[id];store.set('grid-views',JSON.stringify(custom));grid.querySelector('[data-gviews]').innerHTML=viewsHTML();ST.view=id;draw();toast(k,{title:`Saved “${label}”`,v:'success',text:'Saved views are stored in this browser.'});return}
    if((el=t.closest('[data-gcol]'))){setTimeout(()=>{const f=el.dataset.gcol;el.getAttribute('aria-checked')==='true'?ST.cols.add(f):ST.cols.delete(f);store.set('grid-cols',JSON.stringify([...ST.cols]));draw()});return}
    if((el=t.closest('[data-grm]'))){ST.conds.splice(+el.dataset.grm,1);ST.view='';draw();return}
    if(t.closest('[data-gclear]')){ST.conds=[];ST.q='';grid.querySelector('[data-gq]').value='';ST.view='all';draw();return}
    if(t.closest('[data-gprev]')){ST.page--;draw();return}if(t.closest('[data-gnext]')){ST.page++;draw();return}
    if((el=t.closest('[data-gbulkact]'))){const n=ST.sel.size;const act=el.dataset.gbulkact;if(act==='Suspend'){const prev=[...ST.sel].map(id=>[id,USERS.find(u=>u.id===id).status]);prev.forEach(([id])=>USERS.find(u=>u.id===id).status='Suspended');ST.sel.clear();draw();snack(k,`${n} users suspended`,'Undo',()=>{prev.forEach(([id,s])=>USERS.find(u=>u.id===id).status=s);draw()});return}
      if(act==='Export'){const sel=USERS.filter(u=>ST.sel.has(u.id));const csv=['Name,Email,Role,Team,Status',...sel.map(u=>[u.name,u.email,u.role,u.team,u.status].map(x=>`"${x}"`).join(','))].join('\n');try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='users.csv';a.click()}catch(err){}toast(k,{title:`Exported ${n} users`,text:'users.csv (downloads may be blocked in embedded previews).',v:'success'});return}
      toast(k,{title:`${act}: ${n} users`,v:'success'});ST.sel.clear();draw();return}
    if((el=t.closest('[data-quick]'))){e.preventDefault();quick(USERS.find(u=>u.id===el.dataset.quick),el);return}
  });
  grid.addEventListener('change',e=>{const t=e.target;
    if(t.matches('[data-gall]')){$$('[data-grow]',tb).forEach(c=>{const id=c.closest('tr').dataset.id;t.checked?ST.sel.add(id):ST.sel.delete(id)});draw();return}
    if(t.matches('[data-grow]')){const id=t.closest('tr').dataset.id;t.checked?ST.sel.add(id):ST.sel.delete(id);draw();return}
    if(t.matches('[data-grole]')){const u=USERS.find(x=>x.id===t.dataset.grole);const old=u.role;u.role=t.value;snack(k,`${u.name} is now ${u.role}`,'Undo',()=>{u.role=old;draw()});return}
    if(t.matches('[data-gsize]')){ST.size=+t.value;ST.page=1;draw()}});
  grid.querySelector('[data-gq]').addEventListener('input',e=>{ST.q=e.target.value.trim().toLowerCase();ST.page=1;draw()});
  /* filter builder */
  const fb=document.querySelector('[data-fbuilder]');
  if(fb){const rowsBox=fb.querySelector('[data-fb-rows]');const add=(c=['role','is','Administrator'])=>{rowsBox.insertAdjacentHTML('beforeend',`<div class="cond-row"><label class="ds-field"><span class="ds-label">Field</span><select class="n-select" data-fbf>${COLS.filter(x=>x[0]!=='last').map(([f,l])=>`<option value="${f}"${f===c[0]?' selected':''}>${l}</option>`).join('')}</select></label><label class="ds-field"><span class="ds-label">Operator</span><select class="n-select" data-fbo>${['is','is not','contains','starts with'].map(o=>`<option${o===c[1]?' selected':''}>${o}</option>`).join('')}</select></label><label class="ds-field"><span class="ds-label">Value</span><input class="n-select" data-fbv value="${esc(c[2])}"></label><button type="button" class="ds-btn ds-btn--subtle ds-ibtn" aria-label="Remove condition" data-fbx>${ic('x')}</button></div>`)};
    fb.addEventListener('click',e=>{if(e.target.closest('[data-fb-add]'))add(['team','is','Finance']);if(e.target.closest('[data-fbx]'))e.target.closest('.cond-row').remove();if(e.target.closest('[data-fb-apply]')){ST.conds=$$('.cond-row',rowsBox).map(r=>[r.querySelector('[data-fbf]').value,r.querySelector('[data-fbo]').value,r.querySelector('[data-fbv]').value]).filter(c=>c[2]);ST.view='';ST.page=1;draw();toast(k,{title:`${ST.conds.length} filter${ST.conds.length===1?'':'s'} applied`});grid.scrollIntoView({block:'start'})}});add()}
  function quick(u,opener){const L=openLayer(k,`<aside class="ds-drawer ds-drawer--right" role="dialog" aria-labelledby="qv-t"><div class="ds-drawer__head"><h2 id="qv-t">${esc(u.name)}</h2><button type="button" class="ds-btn ds-btn--subtle ds-ibtn ds-s" aria-label="Close" data-close>${ic('x')}</button></div><div class="ds-drawer__body"><div class="profile"><span class="ds-av ds-l" data-c="${u.c}" role="img" aria-label="${esc(u.name)}">${u.ini}</span><div><b>${esc(u.name)}</b><div class="faint small">${u.email}</div></div></div><dl class="dl"><dt>Role</dt><dd>${u.role}</dd><dt>Team</dt><dd>${u.team}</dd><dt>Status</dt><dd><span class="ds-badge ds-badge--${badgeS[u.status]}">${u.status}</span></dd><dt>MFA</dt><dd>${u.mfa?'Enabled':'Not enabled'}</dd><dt>Location</dt><dd>${u.loc}</dd><dt>Last active</dt><dd>${lastTxt(u.last)}</dd><dt>User ID</dt><dd><code>${u.id}</code></dd></dl></div><div class="ds-drawer__foot"><button type="button" class="ds-btn" data-close><span>Close</span></button><button type="button" class="ds-btn ds-btn--primary" data-close data-reset-mfa><span>Reset MFA</span></button></div></aside>`,'drawer',opener);L.querySelector('[data-reset-mfa]').addEventListener('click',()=>toast(k,{title:`MFA reset for ${u.name}`,v:'success',text:'They’ll set it up at next sign-in.'}))}
  draw();
  const h=location.hash.slice(1);if(h==='invite')setTimeout(()=>document.querySelector('[data-tpl="dr-invite"]')?.click(),200);else if(h.startsWith('u'))setTimeout(()=>{const u=USERS.find(x=>x.id===h);if(u)quick(u)},200);
}

/* ---------- approvals with SLA timers ---------- */
const ap=document.querySelector('[data-approvals]');
if(ap){const now=Date.now();$$('[data-due]',ap).forEach(el=>el.dataset.at=now+(+el.dataset.due)*60000);
  const tick=()=>{$$('[data-at]',ap).forEach(el=>{const ms=+el.dataset.at-Date.now();const over=ms<0;const a=Math.abs(ms);const h=Math.floor(a/3600000),m=Math.floor(a%3600000/60000),s=Math.floor(a%60000/1000);el.textContent=(over?'Overdue ':'')+(h?`${h}h `:'')+`${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s`;el.className='sla '+(over?'over':ms<3600000?'warn':'ok')})};tick();setInterval(tick,1000);
  const decide=(rows,what,reason)=>{rows.forEach(r=>{r.querySelector('[data-state]').innerHTML=`<span class="ds-badge ds-badge--${what==='Approved'?'success':'danger'}">${what}</span>`;r.querySelector('[data-at]')?.removeAttribute('data-at');r.querySelector('.sla')&&(r.querySelector('.sla').textContent='—');$$('button,input',r).forEach(b=>{if(!b.closest('[data-chain]'))b.disabled=true});r.querySelector('[data-arow]').checked=false});const c=document.querySelector('[data-ap-count]');if(c)c.textContent=$$('[data-state] .ds-badge--warning',ap).length;toast(k,{title:`${rows.length} request${rows.length>1?'s':''} ${what.toLowerCase()}`,v:what==='Approved'?'success':'warning',text:reason||''})};
  ap.addEventListener('click',e=>{const t=e.target;let el;
    if((el=t.closest('[data-approve]')))decide([el.closest('tr')],'Approved');
    if((el=t.closest('[data-reject]'))){const tr=el.closest('tr');const L=openLayer(k,`<form class="ds-dialog" role="alertdialog" aria-labelledby="rj-t" novalidate style="--dlg-w:460px"><div class="ds-dialog__head"><h2 class="ds-dialog__title" id="rj-t">Reject ${esc(tr.dataset.ref)}?</h2></div><div class="ds-dialog__body"><p>The requester is notified with your reason.</p><div class="ds-field"><label class="ds-label" for="rj-r">Reason<span class="req">*</span></label><div class="ds-control ds-control--area"><textarea id="rj-r" rows="3" required></textarea></div><p class="ds-help">Required</p></div></div><div class="ds-dialog__foot"><button type="button" class="ds-btn" data-close><span>Cancel</span></button><button type="submit" class="ds-btn ds-btn--danger"><span>Reject</span></button></div></form>`,'modal',el);L.querySelector('form').addEventListener('submit',ev=>{ev.preventDefault();const ta=L.querySelector('textarea');if(!ta.value.trim()){ta.closest('.ds-field').classList.add('is-error');ta.closest('.ds-field').querySelector('.ds-help').innerHTML=ic('err')+'Add a reason for the requester';ta.focus();return}L._close();decide([tr],'Rejected','Reason: '+ta.value.trim())})}
    if((el=t.closest('[data-bulk-approve]'))){const rows=$$('[data-arow]:checked',ap).map(c=>c.closest('tr'));if(rows.length)decide(rows,'Approved')}
    
  });
  ap.addEventListener('change',e=>{if(e.target.matches('[data-aall]'))$$('[data-arow]:not(:disabled)',ap).forEach(c=>c.checked=e.target.checked);const n=$$('[data-arow]:checked',ap).length;const b=ap.querySelector('[data-bulk-approve]');b.disabled=!n;b.querySelector('span').textContent=n?`Approve ${n}`:'Approve selected'})}

/* ---------- workflow rule builder ---------- */
const wf=document.querySelector('[data-workflows]');
if(wf){const RULES=store.json('rules',[{id:1,name:'Escalate overdue approvals',on:true,trigger:'Approval is overdue',conds:[['Amount','greater than','10000']],acts:[['Notify','Finance managers'],['Reassign to','Priya Nair']],runs:142},{id:2,name:'Suspend inactive accounts',on:true,trigger:'Every day at 02:00',conds:[['Last active','more than (days)','90']],acts:[['Set status','Suspended'],['Notify','User and manager']],runs:31},{id:3,name:'Welcome new users',on:false,trigger:'User is created',conds:[],acts:[['Send email','Welcome template'],['Add to group','All staff']],runs:0}]);let cur=RULES[0].id;
  const TRIG=['User is created','Approval is overdue','Invoice becomes overdue','Webhook fails 3 times','Every day at 02:00'],FIELDS=['Amount','Team','Role','Region','Last active'],OPS=['is','is not','greater than','less than','more than (days)','contains'],ACTS=['Notify','Reassign to','Set status','Send email','Add to group','Create task','Call webhook'];
  const save=()=>store.set('rules',JSON.stringify(RULES));
  const sel=(opts,v,a)=>`<select class="n-select" ${a}>${opts.map(o=>`<option${o===v?' selected':''}>${o}</option>`).join('')}</select>`;
  const sentence=r=>`When <b>${esc(r.trigger.toLowerCase())}</b>${r.conds.length?' and '+r.conds.map(c=>`<b>${esc(c[0].toLowerCase())} ${esc(c[1])} ${esc(c[2])}</b>`).join(' and '):''}, then ${r.acts.map(a=>`<b>${esc(a[0].toLowerCase())} ${esc(a[1])}</b>`).join(', then ')}.`;
  const drawList=()=>{wf.querySelector('[data-rules]').innerHTML=RULES.map(r=>`<div class="rule-item" role="button" tabindex="0" data-rule="${r.id}" aria-current="${r.id===cur}"><div style="flex:1;min-width:0"><b>${esc(r.name)}</b><span>${r.on?'Active':'Off'} · ${r.runs} runs</span></div><span class="pill"><span class="dot${r.on?'':' off'}"></span>${r.on?'On':'Off'}</span></div>`).join('')};
  const drawEd=()=>{const r=RULES.find(x=>x.id===cur);wf.querySelector('[data-editor]').innerHTML=`<div class="rule"><div class="rule__h"><input class="n-select" style="flex:1;min-width:200px;font-weight:600" value="${esc(r.name)}" data-rname aria-label="Rule name"><label class="ds-switch"><input type="checkbox" role="switch"${r.on?' checked':''} data-ron><span class="ds-switch__track"></span><span>Enabled</span></label></div><div class="rule__b"><div class="rule__step"><b>When</b>${sel(TRIG,r.trigger,'data-rtrig aria-label="Trigger"')}</div><div class="rule__step"><b>If</b><div class="rule__list">${r.conds.map((c,i)=>`<div class="cond-row">${sel(FIELDS,c[0],`data-cf="${i}" aria-label="Condition field"`)}${sel(OPS,c[1],`data-co="${i}" aria-label="Operator"`)}<input class="n-select" value="${esc(c[2])}" data-cv="${i}" aria-label="Value"><button type="button" class="ds-btn ds-btn--subtle ds-ibtn" aria-label="Remove condition" data-cx="${i}">${ic('x')}</button></div>`).join('')||'<span class="faint small" style="padding-top:8px">No conditions: runs every time.</span>'}<div><button type="button" class="ds-btn ds-btn--subtle ds-s" data-cadd>${ic('plus')}<span>Add condition</span></button></div></div></div><div class="rule__step"><b>Then</b><div class="rule__list">${r.acts.map((a,i)=>`<div class="cond-row" style="grid-template-columns:minmax(0,1fr) minmax(0,1.6fr) auto">${sel(ACTS,a[0],`data-af="${i}" aria-label="Action"`)}<input class="n-select" value="${esc(a[1])}" data-av="${i}" aria-label="Action value"><button type="button" class="ds-btn ds-btn--subtle ds-ibtn" aria-label="Remove action" data-ax="${i}">${ic('x')}</button></div>`).join('')}<div><button type="button" class="ds-btn ds-btn--subtle ds-s" data-aadd>${ic('plus')}<span>Add action</span></button></div></div></div><div class="rule__sum" aria-live="polite" data-sum>${sentence(r)}</div></div><div class="cd__f"><button type="button" class="ds-btn ds-btn--subtle" data-rdel>${ic('trash')}<span>Delete</span></button><span class="grow" style="flex:1"></span><button type="button" class="ds-btn" data-rtest>${ic('bolt')}<span>Test run</span></button><button type="button" class="ds-btn ds-btn--primary" data-rsave><span>Save rule</span></button></div></div>`};
  const R=()=>RULES.find(x=>x.id===cur);
  wf.addEventListener('click',e=>{const t=e.target;let el;
    if((el=t.closest('[data-rule]'))){cur=+el.dataset.rule;drawList();drawEd();return}
    if(t.closest('[data-rnew]')){const id=Math.max(...RULES.map(r=>r.id),0)+1;RULES.push({id,name:'New rule',on:false,trigger:TRIG[0],conds:[],acts:[['Notify','Administrators']],runs:0});cur=id;save();drawList();drawEd();wf.querySelector('[data-rname]').select();return}
    if(t.closest('[data-cadd]')){R().conds.push(['Team','is','Finance']);drawEd();return}
    if(t.closest('[data-aadd]')){R().acts.push(['Notify','Team lead']);drawEd();return}
    if((el=t.closest('[data-cx]'))){R().conds.splice(+el.dataset.cx,1);drawEd();return}
    if((el=t.closest('[data-ax]'))){if(R().acts.length>1){R().acts.splice(+el.dataset.ax,1);drawEd()}else toast(k,{title:'A rule needs at least one action',v:'warning'});return}
    if(t.closest('[data-rsave]')){save();drawList();toast(k,{title:'Rule saved',v:'success',text:R().name});return}
    if(t.closest('[data-rtest]')){const r=R();toast(k,{title:`Test run: ${r.name}`,v:'success',text:`Matched ${r.conds.length?7:24} records; ${r.acts.length} action${r.acts.length>1?'s':''} would run. Nothing was changed.`});return}
    if(t.closest('[data-rdel]')){const i=RULES.findIndex(x=>x.id===cur);const [gone]=RULES.splice(i,1);cur=RULES[0]?.id;save();drawList();RULES.length?drawEd():wf.querySelector('[data-editor]').innerHTML='<p class="faint">No rules yet.</p>';snack(k,`Deleted “${gone.name}”`,'Undo',()=>{RULES.splice(i,0,gone);cur=gone.id;save();drawList();drawEd()})}});
  wf.addEventListener('keydown',e=>{const el=e.target.closest('[data-rule]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}});
  wf.addEventListener('input',e=>{const t=e.target,r=R();if(!r)return;if(t.matches('[data-rname]'))r.name=t.value;if(t.matches('[data-cv]'))r.conds[+t.dataset.cv][2]=t.value;if(t.matches('[data-av]'))r.acts[+t.dataset.av][1]=t.value;wf.querySelector('[data-sum]').innerHTML=sentence(r)});
  wf.addEventListener('change',e=>{const t=e.target,r=R();if(!r)return;if(t.matches('[data-ron]')){r.on=t.checked;save();drawList()}if(t.matches('[data-rtrig]'))r.trigger=t.value;if(t.matches('[data-cf]'))r.conds[+t.dataset.cf][0]=t.value;if(t.matches('[data-co]'))r.conds[+t.dataset.co][1]=t.value;if(t.matches('[data-af]'))r.acts[+t.dataset.af][0]=t.value;wf.querySelector('[data-sum]').innerHTML=sentence(r)});
  drawList();drawEd();if(location.hash==='#new')wf.querySelector('[data-rnew]').click();}

/* ---------- data import wizard ---------- */
const im=document.querySelector('[data-import]');
if(im){let step=0,data=null,map={};const TARGET=['Full name','Email','Role','Team','— Skip —'];const SAMPLE='name,email,role,department\nSam Rivera,sam.rivera@ledger.example,Editor,Sales\nYuki Tanaka,yuki.tanaka@ledger,Viewer,Finance\nOla Nordmann,ola.nordmann@ledger.example,Owner,Engineering\nRavi Kumar,ravi.kumar@ledger.example,Viewer,Support\n,missing.name@ledger.example,Editor,Design\nLea Müller,lea.mueller@ledger.example,Administrator,Legal';
  const parse=txt=>{const lines=txt.trim().split(/\r?\n/).filter(Boolean);const split=l=>l.match(/("([^"]|"")*"|[^,]*)(,|$)/g).slice(0,-1).map(c=>c.replace(/,$/,'').replace(/^"|"$/g,'').replace(/""/g,'"').trim());return {head:split(lines[0]),rows:lines.slice(1).map(split)}};
  const guess=h=>/name/i.test(h)?'Full name':/mail/i.test(h)?'Email':/role/i.test(h)?'Role':/team|dep/i.test(h)?'Team':'— Skip —';
  const steps=$$('.dx-st__s',im);const panels=$$('[data-ip]',im);
  const go=n=>{step=n;steps.forEach((s,i)=>{s.className='dx-st__s '+(i<n?'is-done':i===n?'is-cur':'is-up');s.toggleAttribute('aria-current',i===n);s.querySelector('.dx-st__dot').innerHTML=i<n?ic('check'):String(i+1)});panels.forEach((p,i)=>p.hidden=i!==n);if(n===1)drawMap();if(n===2)drawVal();if(n===3)run();im.querySelector('[data-ip-focus="'+n+'"]')?.focus()};
  const load=txt=>{data=parse(txt);map={};data.head.forEach(h=>map[h]=guess(h));im.querySelector('[data-ifile]').textContent=`${data.rows.length} rows · ${data.head.length} columns detected`;im.querySelector('[data-inext0]').disabled=false};
  const drawMap=()=>{im.querySelector('[data-map]').innerHTML=data.head.map(h=>`<div class="map-row"><code>${esc(h)}</code>${ic('chev-right')}<select class="n-select" data-mapf="${esc(h)}" aria-label="Map ${esc(h)} to">${TARGET.map(t=>`<option${map[h]===t?' selected':''}>${t}</option>`).join('')}</select><span class="faint small">e.g. ${esc(data.rows[0]?.[data.head.indexOf(h)]||'—')}</span></div>`).join('')};
  const check=r=>{const o={};data.head.forEach((h,i)=>{if(map[h]!=='— Skip —')o[map[h]]=r[i]||''});const errs={};if(!o['Full name'])errs['Full name']='Missing';if(!/^\S+@\S+\.\S+$/.test(o.Email||''))errs.Email='Invalid email';if(o.Role&&!['Administrator','Billing admin','Editor','Viewer','Auditor'].includes(o.Role))errs.Role='Unknown role';return [o,errs]};
  const drawVal=()=>{const res=data.rows.map(check);const bad=res.filter(r=>Object.keys(r[1]).length).length;im.querySelector('[data-vsum]').innerHTML=`<div class="toolbar"><span class="pill"><span class="dot"></span>${res.length-bad} ready</span><span class="pill"><span class="dot err"></span>${bad} with problems</span></div>`;const cols=['Full name','Email','Role','Team'];im.querySelector('[data-vtable]').innerHTML=`<div class="ds-tablewrap"><table class="ds-table"><caption class="ds-sr">Validation preview</caption><thead><tr><th scope="col">Row</th>${cols.map(c=>`<th scope="col">${c}</th>`).join('')}<th scope="col">Status</th></tr></thead><tbody>${res.map(([o,er],i)=>`<tr><td class="num">${i+2}</td>${cols.map(c=>`<td${er[c]?' class="bad"':''}>${esc(o[c]||'—')}${er[c]?` <span class="small">(${er[c]})</span>`:''}</td>`).join('')}<td>${Object.keys(er).length?'<span class="ds-badge ds-badge--danger">Skip</span>':'<span class="ds-badge ds-badge--success">Ready</span>'}</td></tr>`).join('')}</tbody></table></div>`;im.dataset.ok=res.length-bad;im.dataset.bad=bad};
  const run=()=>{const bar=im.querySelector('[data-ibar]'),lab=im.querySelector('[data-ilab]'),done=im.querySelector('[data-idone]');done.hidden=true;let v=0;const t=setInterval(()=>{v=Math.min(100,v+7);bar.style.setProperty('--v',v+'%');bar.parentElement.setAttribute('aria-valuenow',v);lab.textContent=v+'%';if(v>=100){clearInterval(t);done.hidden=false;done.querySelector('[data-isum]').textContent=`${im.dataset.ok} users imported, ${im.dataset.bad} skipped. Invitations will be sent within a few minutes.`;steps[3].className='dx-st__s is-done';steps[3].querySelector('.dx-st__dot').innerHTML=ic('check')}},120)};
  im.addEventListener('click',e=>{const t=e.target;if(t.closest('[data-isample]')){load(SAMPLE);toast(k,{title:'Sample file loaded',text:'6 rows; 3 have problems to fix.'})}if(t.closest('[data-inext0]'))go(1);if(t.closest('[data-inext1]'))go(2);if(t.closest('[data-inext2]'))go(3);if(t.closest('[data-iback]'))go(step-1);if(t.closest('[data-irestart]')){data=null;im.querySelector('[data-ifile]').textContent='No file selected';im.querySelector('[data-inext0]').disabled=true;go(0)}});
  im.addEventListener('change',e=>{if(e.target.matches('[data-iinput]')){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>load(String(r.result));r.readAsText(f)}if(e.target.matches('[data-mapf]'))map[e.target.dataset.mapf]=e.target.value});
  go(0)}

/* ---------- report builder ---------- */
const rb=document.querySelector('[data-rbuilder]');
if(rb){const DATA={Revenue:{Month:[['May',64],['Jun',70],['Jul',73],['Aug',71],['Sep',78],['Oct',84]],Region:[['Europe',182],['North America',151],['Asia Pacific',62],['Latin America',25]],Channel:[['Web',196],['Sales team',122],['Partner',71],['Marketplace',31]]},Orders:{Month:[['May',980],['Jun',1040],['Jul',1102],['Aug',1088],['Sep',1190],['Oct',1284]],Region:[['Europe',2810],['North America',2402],['Asia Pacific',910],['Latin America',372]],Channel:[['Web',3120],['Sales team',1890],['Partner',1104],['Marketplace',380]]},'Active users':{Month:[['May',3310],['Jun',3420],['Jul',3550],['Aug',3610],['Sep',3780],['Oct',3912]],Region:[['Europe',1702],['North America',1388],['Asia Pacific',604],['Latin America',218]],Channel:[['Web',2410],['Sales team',380],['Partner',902],['Marketplace',220]]}};
  const fmt=(m,v)=>m==='Revenue'?new Intl.NumberFormat(LOC,{style:'currency',currency:CUR,maximumFractionDigits:0}).format(v*1000):new Intl.NumberFormat(LOC).format(v);
  const draw=()=>{const m=rb.querySelector('[data-rm]').value,d=rb.querySelector('[data-rd]').value,c=rb.querySelector('[data-rc]').value;const rows=DATA[m][d];const max=Math.max(...rows.map(r=>r[1]))*1.15;const W=640,H=240,pl=56,pr=12,pt=16,pb=30;const n=rows.length;const bw=(W-pl-pr)/n;const y=v=>pt+(H-pt-pb)*(1-v/max);const x=i=>pl+bw*i+bw/2;
    const grid=[0,.5,1].map(f=>`<line class="grid" x1="${pl}" x2="${W-pr}" y1="${y(max*f)}" y2="${y(max*f)}"/><text x="${pl-8}" y="${y(max*f)+4}" text-anchor="end">${m==='Revenue'?Math.round(max*f)+'k':Math.round(max*f)}</text>`).join('');
    let body;if(c==='Line'){const p=rows.map((r,i)=>`${x(i)},${y(r[1])}`).join(' L');body=`<path class="ar" d="M${p} L${x(n-1)},${y(0)} L${x(0)},${y(0)}Z"/><path class="ln" d="M${p}"/>`+rows.map((r,i)=>`<circle class="pt" cx="${x(i)}" cy="${y(r[1])}" r="3.5"><title>${r[0]}: ${fmt(m,r[1])}</title></circle>`).join('')}else body=rows.map((r,i)=>`<rect class="s1" x="${x(i)-bw*.3}" y="${y(r[1])}" width="${bw*.6}" height="${y(0)-y(r[1])}" rx="2"><title>${r[0]}: ${fmt(m,r[1])}</title></rect><text class="lbl" x="${x(i)}" y="${y(r[1])-5}" text-anchor="middle">${fmt(m,r[1])}</text>`).join('');
    rb.querySelector('[data-rchart]').innerHTML=c==='Table'?'':`<svg class="dx-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${m} by ${d.toLowerCase()}: ${rows.map(r=>r[0]+' '+fmt(m,r[1])).join(', ')}">${grid}${body}${rows.map((r,i)=>`<text x="${x(i)}" y="${H-9}" text-anchor="middle">${r[0]}</text>`).join('')}</svg>`;
    rb.querySelector('[data-rtable]').innerHTML=`<div class="ds-tablewrap"><table class="ds-table"><caption class="ds-sr">${m} by ${d}</caption><thead><tr><th scope="col">${d}</th><th scope="col" class="num">${m}</th><th scope="col" class="num">Share</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td class="num">${fmt(m,r[1])}</td><td class="num">${Math.round(r[1]/rows.reduce((a,b)=>a+b[1],0)*100)}%</td></tr>`).join('')}</tbody></table></div>`;
    rb.querySelector('[data-rtitle]').textContent=`${m} by ${d.toLowerCase()}`};
  rb.addEventListener('change',draw);draw()}

/* ---------- audit diff ---------- */
document.addEventListener('click',e=>{const el=e.target.closest('[data-diff]');if(!el)return;e.preventDefault();const d=JSON.parse(el.dataset.diff);const lines=d.lines.map(([t,s])=>`<div class="${t}">${esc(s)}</div>`).join('');openLayer(k,`<aside class="ds-drawer ds-drawer--right" role="dialog" aria-labelledby="df-t"><div class="ds-drawer__head"><h2 id="df-t">${esc(d.title)}</h2><button type="button" class="ds-btn ds-btn--subtle ds-ibtn ds-s" aria-label="Close" data-close>${ic('x')}</button></div><div class="ds-drawer__body"><dl class="dl"><dt>Actor</dt><dd>${esc(d.actor)}</dd><dt>When</dt><dd>${esc(d.when)}</dd><dt>IP</dt><dd><code>${esc(d.ip)}</code></dd><dt>Request ID</dt><dd><code>${esc(d.req)}</code></dd></dl><h3 style="margin:8px 0 0;font-size:14px">Changes</h3><div class="diff" role="region" aria-label="Before and after">${lines}</div></div><div class="ds-drawer__foot"><button type="button" class="ds-btn" data-close><span>Close</span></button><button type="button" class="ds-btn ds-btn--primary" data-close data-save="Change reverted (demo)"><span>Revert change</span></button></div></aside>`,'drawer',el)});

/* ---------- security center ---------- */
const sec=document.querySelector('[data-security]');
if(sec){const ring=sec.querySelector('.ds-ring');const recalc=()=>{const checks=$$('[data-score]',sec);let s=53;checks.forEach(c=>{if(c.checked)s+=+c.dataset.score});const ip=$$('[data-ip-item]',sec).length;if(ip)s+=5;s=Math.min(100,s);ring.style.setProperty('--v',s);ring.setAttribute('aria-valuenow',s);ring.querySelector('span').textContent=s;sec.querySelector('[data-score-label]').textContent=s>=85?'Strong':s>=65?'Good, with gaps':'Needs attention';$$('[data-check-for]',sec).forEach(li=>{const on=sec.querySelector(li.dataset.checkFor)?.checked;li.querySelector('.ds-ic').outerHTML=on?ic('ok'):ic('warn');li.className=on?'ok':'no'})};
  sec.addEventListener('change',e=>{if(e.target.matches('[data-score]')){recalc();toast(k,{title:'Policy updated',text:e.target.closest('label').textContent.trim()})}});
  const ipForm=sec.querySelector('[data-ipform]');ipForm.addEventListener('submit',e=>{e.preventDefault();const i=ipForm.querySelector('input');const v=i.value.trim();const ok=/^(\d{1,3}\.){3}\d{1,3}(\/(\d|[12]\d|3[0-2]))?$/.test(v)&&v.split('/')[0].split('.').every(n=>+n<=255);const f=i.closest('.ds-field');f.classList.toggle('is-error',!ok);f.querySelector('.ds-help').innerHTML=ok?'IPv4 address or CIDR range, e.g. 203.0.113.0/24':ic('err')+'Enter an IPv4 address or CIDR range, for example 203.0.113.0/24';if(!ok){i.focus();return}sec.querySelector('[data-iplist]').insertAdjacentHTML('beforeend',`<li data-ip-item class="chip-x" style="height:28px"><code>${esc(v)}</code><button type="button" aria-label="Remove ${esc(v)}" data-iprm>${ic('x')}</button></li>`);i.value='';recalc();toast(k,{title:`${v} added to allowlist`,v:'success'})});
  sec.addEventListener('click',e=>{const b=e.target.closest('[data-iprm]');if(b){b.closest('li').remove();recalc()}});recalc()}

/* ---------- integrations ---------- */
const ig=document.querySelector('[data-integrations]');
if(ig){ig.addEventListener('click',e=>{const t=e.target;let el;
  if((el=t.closest('[data-retry]'))){const tr=el.closest('tr');el.disabled=true;el.setAttribute('aria-busy','true');setTimeout(()=>{tr.querySelector('[data-dstatus]').innerHTML='<span class="ds-badge ds-badge--success">200 OK</span>';tr.querySelector('[data-dtries]').textContent=+tr.querySelector('[data-dtries]').textContent+1;el.removeAttribute('aria-busy');el.remove();toast(k,{title:'Delivery succeeded',v:'success'})},900)}
  if(t.closest('[data-test-event]')){const tb=ig.querySelector('[data-deliveries] tbody');const id='evt_'+Math.random().toString(36).slice(2,8);tb.insertAdjacentHTML('afterbegin',`<tr class="is-new"><td><code class="keyv">${id}</code></td><td>test.ping</td><td>https://hooks.northwind.example/ledger</td><td data-dstatus><span class="ds-badge ds-badge--success">200 OK</span></td><td class="num" data-dtries>1</td><td>Just now</td><td></td></tr>`);toast(k,{title:'Test event delivered',v:'success',text:id})}
  if(t.closest('[data-newkey]')||location.hash==='#key'&&false){}
});
  const nk=()=>{const key='lk_live_'+Array.from({length:32},()=>'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random()*36)]).join('');const L=openLayer(k,`<form class="ds-dialog" role="dialog" aria-labelledby="nk-t" novalidate style="--dlg-w:520px"><div class="ds-dialog__head"><h2 class="ds-dialog__title" id="nk-t">Create API key</h2></div><div class="ds-dialog__body" data-nk1><div class="ds-field"><label class="ds-label" for="nk-n">Name<span class="req">*</span></label><div class="ds-control"><input id="nk-n" required placeholder="e.g. Data warehouse sync"></div></div><fieldset class="ds-choices"><legend class="ds-label">Scopes</legend>${['users:read','users:write','orders:read','billing:read','audit:read'].map((s,i)=>`<label class="ds-check"><input type="checkbox"${i===0||i===2?' checked':''}><span class="ds-check__box"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5 9.5 17 19 7"/></svg></span><span class="ds-check__txt"><code>${s}</code></span></label>`).join('')}</fieldset><label class="ds-field"><span class="ds-label">Expires</span><select class="n-select"><option>In 90 days</option><option>In 1 year</option><option>Never</option></select></label></div><div class="ds-dialog__body" data-nk2 hidden><div class="ds-alert ds-alert--warning" role="status"><span class="ds-alert__ic">${ic('warn')}</span><div class="ds-alert__body"><p class="ds-alert__title">Copy this key now</p><p class="ds-alert__text">You won’t be able to see it again.</p></div></div><div class="keybox"><span style="flex:1">${key}</span><button type="button" class="ds-btn ds-ibtn ds-s" aria-label="Copy key" data-copy="${key}">${ic('copy')}</button></div></div><div class="ds-dialog__foot"><button type="button" class="ds-btn" data-close><span>Cancel</span></button><button type="submit" class="ds-btn ds-btn--primary"><span>Create key</span></button></div></form>`);const f=L.querySelector('form');f.addEventListener('submit',e=>{e.preventDefault();const n=f.querySelector('#nk-n');if(!f.querySelector('[data-nk2]').hidden){L._close();return}if(!n.value.trim()){n.closest('.ds-field').classList.add('is-error');n.focus();return}f.querySelector('[data-nk1]').hidden=true;f.querySelector('[data-nk2]').hidden=false;f.querySelector('[type=submit] span').textContent='Done';f.querySelector('[data-close]').hidden=true;const tb=document.querySelector('[data-keys] tbody');if(tb)tb.insertAdjacentHTML('afterbegin',`<tr class="is-new"><td>${esc(n.value.trim())}</td><td><code class="keyv">${key.slice(0,8)}••••${key.slice(-4)}</code></td><td>Today</td><td>Never</td><td></td></tr>`)})};
  document.addEventListener('click',e=>{if(e.target.closest('[data-newkey]'))nk()});if(location.hash==='#key')setTimeout(nk,200)}

/* ---------- feature flags ---------- */
const ff=document.querySelector('[data-flags]');
if(ff){const ENV=['Development','Staging','Production'];let env=2;const FL=store.json('flags',{'new-checkout':[[1,100],[1,50],[1,10]],'bulk-approvals':[[1,100],[1,100],[1,100]],'ai-summaries':[[1,100],[0,0],[0,0]],'dark-reports':[[1,100],[1,100],[0,0]],'usage-billing-v2':[[1,100],[1,25],[0,0]]});const META={'new-checkout':'Redesigned checkout flow','bulk-approvals':'Approve up to 50 requests at once','ai-summaries':'Generated summaries on records','dark-reports':'Dark theme for exported reports','usage-billing-v2':'Metered billing engine'};
  const draw=()=>{ff.querySelector('[data-flist]').innerHTML=Object.entries(FL).map(([id,v])=>`<div class="flag-row"><div><b>${META[id]}</b><div><code>${id}</code></div></div><div><span class="pill"><span class="dot${v[env][0]?'':' off'}"></span>${v[env][0]?'Serving':'Off'} in ${ENV[env]}</span></div><label class="roll">Rollout <b data-rl="${id}">${v[env][1]}%</b><input type="range" class="ds-range" min="0" max="100" step="5" value="${v[env][1]}" data-roll="${id}" aria-label="Rollout percentage for ${id}"${v[env][0]?'':' disabled'}></label><label class="ds-switch" style="justify-self:end"><input type="checkbox" role="switch" data-ftog="${id}"${v[env][0]?' checked':''} aria-label="${id} in ${ENV[env]}"><span class="ds-switch__track"></span></label></div>`).join('');$$('.ds-range',ff).forEach(updRange);ff.querySelector('[data-env-warn]').hidden=env!==2};
  ff.addEventListener('ds-tab',e=>{env=+e.detail.tab.dataset.env;draw()});
  ff.addEventListener('input',e=>{const r=e.target.closest('[data-roll]');if(r){FL[r.dataset.roll][env][1]=+r.value;ff.querySelector(`[data-rl="${r.dataset.roll}"]`).textContent=r.value+'%'}});
  ff.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-ftog]')){FL[t.dataset.ftog][env][0]=t.checked?1:0;store.set('flags',JSON.stringify(FL));draw();toast(k,{title:`${t.dataset.ftog} ${t.checked?'enabled':'disabled'} in ${ENV[env]}`,v:env===2?'warning':'info'})}if(t.matches('[data-roll]')){store.set('flags',JSON.stringify(FL));toast(k,{title:`${t.dataset.roll}: ${t.value}% of ${ENV[env]} users`})}});
  draw()}

/* ---------- branding accent (settings) ---------- */
const accent=store.get('accent','');if(accent)document.body.style.setProperty('--f-color-primary',accent);
document.addEventListener('click',e=>{const b=e.target.closest('[data-accent]');if(!b)return;$$('[data-accent]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const c=b.dataset.accent;if(c){document.body.style.setProperty('--f-color-primary',c);document.body.style.setProperty('--f-color-primary-hover',`color-mix(in srgb,${c} 85%,#000)`);document.body.style.setProperty('--f-color-primary-pressed',`color-mix(in srgb,${c} 72%,#000)`)}else{['--f-color-primary','--f-color-primary-hover','--f-color-primary-pressed'].forEach(p=>document.body.style.removeProperty(p))}store.set('accent',c);toast(k,{title:'Brand colour applied',text:'Stored in this browser for the demo.'})});
if(accent){document.body.style.setProperty('--f-color-primary-hover',`color-mix(in srgb,${accent} 85%,#000)`);document.body.style.setProperty('--f-color-primary-pressed',`color-mix(in srgb,${accent} 72%,#000)`);$$('[data-accent]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.accent===accent)))}
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-locale]')){store.set('locale',t.value);toast(k,{title:'Region updated',text:'Numbers and dates now use '+t.options[t.selectedIndex].text+'. Reloading…'});setTimeout(()=>location.reload(),900)}if(t.matches('[data-currency]')){store.set('currency',t.value);setTimeout(()=>location.reload(),300)}});
$$('[data-locale]').forEach(s=>s.value=LOC);$$('[data-currency]').forEach(s=>s.value=CUR);
document.addEventListener('click',e=>{const b=e.target.closest('[data-test-sso]');if(!b)return;b.setAttribute('aria-busy','true');setTimeout(()=>{b.removeAttribute('aria-busy');const out=document.querySelector('[data-sso-result]');out.hidden=false;toast(k,{title:'SSO connection verified',v:'success',text:'Signed assertion received from the identity provider.'})},1200)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-scim-token]');if(!b)return;const t='scim_'+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);const out=document.querySelector('[data-scim-out]');out.hidden=false;out.querySelector('span').textContent=t;out.querySelector('[data-copy]').dataset.copy=t;toast(k,{title:'New SCIM token generated',v:'warning',text:'The previous token stops working in 24 hours.'})});

/* ---------- status page ticker ---------- */
const st=document.querySelector('[data-updated]');if(st){let s=0;setInterval(()=>{s++;st.textContent=s<60?`${s}s ago`:`${Math.floor(s/60)} min ago`},1000)}

/* ---------- MFA sign-in ---------- */
const mfa=document.querySelector('[data-mfa]');
if(mfa){const s1=mfa.querySelector('[data-s1]'),s2=mfa.querySelector('[data-s2]');s1.addEventListener('submit',e=>{e.preventDefault();const bad=$$('[required]',s1).filter(i=>!i.value.trim()||(i.type==='email'&&!/^\S+@\S+\.\S+$/.test(i.value)));$$('.ds-field',s1).forEach(f=>f.classList.remove('is-error'));bad.forEach(i=>i.closest('.ds-field').classList.add('is-error'));if(bad.length){bad[0].focus();return}s1.hidden=true;s2.hidden=false;s2.querySelector('input').focus()});
  const ins=$$('.otp input',s2);ins.forEach((i,n)=>{i.addEventListener('input',()=>{i.value=i.value.replace(/\D/g,'').slice(-1);if(i.value&&ins[n+1])ins[n+1].focus();if(ins.every(x=>x.value))s2.requestSubmit()});i.addEventListener('keydown',e=>{if(e.key==='Backspace'&&!i.value&&ins[n-1])ins[n-1].focus()});i.addEventListener('paste',e=>{const d=(e.clipboardData.getData('text')||'').replace(/\D/g,'').slice(0,6);if(d.length===6){e.preventDefault();ins.forEach((x,j)=>x.value=d[j]);s2.requestSubmit()}})});
  s2.addEventListener('submit',e=>{e.preventDefault();const code=ins.map(i=>i.value).join('');if(code.length<6){ins.find(i=>!i.value).focus();return}toast(k,{title:'Signed in (demo)',v:'success',text:'Any 6 digits work here. Nothing was sent.'});setTimeout(()=>location.href='index.html',800)});
  s2.querySelector('[data-back]').addEventListener('click',()=>{s2.hidden=true;s1.hidden=false})}
})();
